// GENERATED by scripts/sync-functions.mjs from src/shared. Do not edit; run `npm run functions:sync`.
// Text of push notifications and reminder messages, in the recipient's
// language. Pure TS: used by the app (reminders shared via messengers) and by
// the `push` Edge Function (a generated copy lives in supabase/functions/_shared).

import { formatDate, formatMoney, type FormatContext } from './format.ts';

export type Tone = 'gentle' | 'neutral' | 'firm';

export type NotificationKind =
  | 'loan_confirmed'
  | 'loan_disputed'
  | 'loan_changed'
  | 'repayment_new'
  | 'repayment_recorded'
  | 'repayment_confirmed'
  | 'repayment_disputed'
  | 'settled'
  | 'reminder'
  | 'due_today';

/** Payload written by public.loan_payload() plus event-specific fields. */
export interface NotificationData {
  loan_id: string;
  name: string;
  amount_minor: number;
  currency: string;
  remaining_minor: number;
  repayment_minor?: number;
  comment?: string | null;
  tone?: Tone;
  greet_name?: string | null;
  loan_date?: string;
  borrower_has_app?: boolean;
}

export type Translate = (key: string, params?: Record<string, string>) => string;

const TONE_KEY: Record<Tone, string> = {
  gentle: 'reminders.messageGentle',
  neutral: 'reminders.messageNeutral',
  firm: 'reminders.messageFirm',
};

/** The reminder text itself ("Hi Sara, just a friendly note about…"). */
export function reminderMessage(
  tone: Tone,
  v: { greetName: string; amountMinor: number; currency: string; loanDate: string },
  t: Translate,
  fmt: FormatContext,
): string {
  return t(TONE_KEY[tone], {
    name: v.greetName,
    amount: formatMoney(v.amountMinor, v.currency, fmt),
    date: formatDate(v.loanDate, fmt),
  });
}

/** Isolate a name so mixed scripts read correctly ("Sara" inside Persian text). */
const iso = (s: string) => `⁨${s}⁩`;

export function renderNotification(
  kind: NotificationKind,
  d: NotificationData,
  t: Translate,
  fmt: FormatContext,
): { title: string; body: string } {
  const money = (minor: number | undefined) => formatMoney(minor ?? 0, d.currency, fmt);
  const params: Record<string, string> = {
    name: iso(d.name),
    amount: money(d.amount_minor),
    remaining: money(d.remaining_minor),
    repayment: money(d.repayment_minor),
    comment: d.comment ?? '',
  };
  if (kind === 'reminder') {
    return {
      title: t('push.reminderTitle', params),
      body: reminderMessage(
        d.tone ?? 'gentle',
        { greetName: iso(d.greet_name ?? ''), amountMinor: d.remaining_minor, currency: d.currency, loanDate: d.loan_date ?? '' },
        t,
        fmt,
      ),
    };
  }
  const bodyKey = kind === 'due_today' && d.borrower_has_app === false ? 'push.due_todayBodyNoApp' : `push.${kind}Body`;
  return { title: t(`push.${kind}Title`, params), body: t(bodyKey, params) };
}
